// Formula parsing and evaluation. The AST shape is private to this module.
import { colIndex, toAddr } from "./addr.mjs";

const REF = /^\$?([A-Za-z]{1,3})\$?([1-9]\d*)(?![A-Za-z0-9_.(])/;
const NUM = /^(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/;
const ID = /^[A-Za-z_][A-Za-z0-9_.]*/;
const OPS = ["<=", ">=", "<>", "=", "<", ">", "&", "+", "-", "*", "/", "^", "(", ")", ",", ":"];

function tokenize(text) {
  const out = [];
  let i = 0;
  while (i < text.length) {
    const rest = text.slice(i);
    let m;
    if (/^\s/.test(rest)) { i++; continue; }
    if ((m = NUM.exec(rest))) {
      out.push({ t: "num", v: Number(m[0]) });
    } else if (rest[0] === '"') {
      let j = 1, s = "";
      for (;;) {
        if (j >= rest.length) throw new SyntaxError("unterminated string");
        if (rest[j] === '"') {
          if (rest[j + 1] === '"') { s += '"'; j += 2; continue; }
          break;
        }
        s += rest[j++];
      }
      out.push({ t: "str", v: s });
      i += j + 1;
      continue;
    } else if ((m = REF.exec(rest))) {
      out.push({ t: "ref", v: toAddr(colIndex(m[1]), Number(m[2]) - 1) });
    } else if ((m = ID.exec(rest))) {
      out.push({ t: "id", v: m[0] });
    } else {
      const op = OPS.find((o) => rest.startsWith(o));
      if (!op) throw new SyntaxError(`unexpected character ${rest[0]}`);
      out.push({ t: "op", v: op });
      i += op.length;
      continue;
    }
    i += m[0].length;
  }
  out.push({ t: "eof" });
  return out;
}

// Parses formula text (without the leading "="). Throws SyntaxError on bad syntax.
export function parseFormula(text) {
  const toks = tokenize(String(text));
  let p = 0;
  const peek = () => toks[p];
  const isOp = (v) => toks[p].t === "op" && toks[p].v === v;
  const expect = (v) => {
    if (!isOp(v)) throw new SyntaxError(`expected ${v}`);
    p++;
  };
  const binary = (next, ops) => () => {
    let left = next();
    while (peek().t === "op" && ops.includes(peek().v)) {
      const op = toks[p++].v;
      left = { k: "bin", op, l: left, r: next() };
    }
    return left;
  };
  const unary = () => {
    if (isOp("-") || isOp("+")) {
      const op = toks[p++].v;
      return { k: "un", op, x: unary() };
    }
    return primary();
  };
  const primary = () => {
    const tok = toks[p++];
    if (tok.t === "num") return { k: "lit", v: tok.v };
    if (tok.t === "str") return { k: "lit", v: tok.v };
    if (tok.t === "ref") {
      if (isOp(":")) {
        p++;
        const end = toks[p++];
        if (end.t !== "ref") throw new SyntaxError("bad range");
        return { k: "range", a: tok.v, b: end.v };
      }
      return { k: "ref", a: tok.v };
    }
    if (tok.t === "id") {
      if (isOp("(")) {
        p++;
        const args = [];
        if (!isOp(")")) {
          do args.push(expr()); while (isOp(",") && p++);
        }
        expect(")");
        return { k: "call", name: tok.v.toUpperCase(), args };
      }
      const u = tok.v.toUpperCase();
      if (u === "TRUE" || u === "FALSE") return { k: "lit", v: u === "TRUE" };
      throw new SyntaxError(`unknown identifier ${tok.v}`);
    }
    if (tok.t === "op" && tok.v === "(") {
      const e = expr();
      expect(")");
      return e;
    }
    throw new SyntaxError("unexpected token");
  };
  const pow = binary(unary, ["^"]);
  const mul = binary(pow, ["*", "/"]);
  const add = binary(mul, ["+", "-"]);
  const cat = binary(add, ["&"]);
  const expr = binary(cat, ["=", "<>", "<", ">", "<=", ">="]);
  const ast = expr();
  if (peek().t !== "eof") throw new SyntaxError("unexpected token");
  return ast;
}

function rangeAddrs(node) {
  const split = (a) => /^([A-Z]+)(\d+)$/.exec(a);
  const [, c1, r1] = split(node.a), [, c2, r2] = split(node.b);
  const [x1, x2] = [colIndex(c1), colIndex(c2)].sort((a, b) => a - b);
  const [y1, y2] = [Number(r1) - 1, Number(r2) - 1].sort((a, b) => a - b);
  const out = [];
  for (let y = y1; y <= y2; y++) for (let x = x1; x <= x2; x++) out.push(toAddr(x, y));
  return out;
}

// Normalized cell addresses (no "$", upper case) the formula reads: ranges expanded
// row by row, each address once, in order of first appearance.
export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    if (n.k === "ref") seen.add(n.a);
    else if (n.k === "range") rangeAddrs(n).forEach((a) => seen.add(a));
    else if (n.k === "bin") { walk(n.l); walk(n.r); }
    else if (n.k === "un") walk(n.x);
    else if (n.k === "call") n.args.forEach(walk);
  };
  walk(ast);
  return [...seen];
}

const isErr = (v) => typeof v === "string" && v.startsWith("#");
const NUMBER = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/;

function toNum(v) {
  if (v === null) return 0;
  if (typeof v === "number") return v;
  if (typeof v === "boolean") return v ? 1 : 0;
  const t = v.trim();
  return NUMBER.test(t) ? Number(t) : "#VALUE!";
}

function toText(v) {
  if (v === null) return "";
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

function toBool(v) {
  if (v === null) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  const u = v.toUpperCase();
  return u === "TRUE" ? true : u === "FALSE" ? false : "#VALUE!";
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null && b === null) return 0;
  const dflt = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? "" : false);
  if (a === null) a = dflt(b);
  if (b === null) b = dflt(a);
  if (rank(a) !== rank(b)) return rank(a) - rank(b);
  if (typeof a === "string") { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

const finite = (n) => (Number.isFinite(n) ? n + 0 : "#NUM!");

const shift = (x, n) => {
  const [m, e = "0"] = String(x).split("e");
  return Number(`${m}e${Number(e) + n}`);
};

function round(x, d) {
  d = Math.trunc(d);
  const r = shift(Math.round(shift(Math.abs(x), d)), -d);
  return Math.sign(x) * r;
}

const ARITY = {
  IF: [2, 3], NOT: [1, 1], ROUND: [2, 2], ABS: [1, 1], LEN: [1, 1], UPPER: [1, 1], LOWER: [1, 1],
  SUM: [0, Infinity], AVERAGE: [0, Infinity], MIN: [0, Infinity], MAX: [0, Infinity],
  COUNT: [0, Infinity], AND: [1, Infinity], OR: [1, Infinity], CONCAT: [0, Infinity],
};

// The formula's value. lookup(addr) returns a cell's value (null if empty).
export function evaluate(ast, lookup) {
  const ev = (n) => {
    switch (n.k) {
      case "lit": return n.v;
      case "ref": return lookup(n.a);
      case "range": return "#VALUE!";
      case "un": {
        const x = ev(n.x);
        if (isErr(x)) return x;
        const v = toNum(x);
        return isErr(v) ? v : finite(n.op === "-" ? -v : v);
      }
      case "bin": return binary(n);
      case "call": return call(n);
    }
  };

  const binary = (n) => {
    const l = ev(n.l);
    if (isErr(l)) return l;
    const r = ev(n.r);
    if (isErr(r)) return r;
    switch (n.op) {
      case "&": return toText(l) + toText(r);
      case "=": return compare(l, r) === 0;
      case "<>": return compare(l, r) !== 0;
      case "<": return compare(l, r) < 0;
      case ">": return compare(l, r) > 0;
      case "<=": return compare(l, r) <= 0;
      case ">=": return compare(l, r) >= 0;
    }
    const a = toNum(l);
    if (isErr(a)) return a;
    const b = toNum(r);
    if (isErr(b)) return b;
    switch (n.op) {
      case "+": return finite(a + b);
      case "-": return finite(a - b);
      case "*": return finite(a * b);
      case "/": return b === 0 ? "#DIV/0!" : finite(a / b);
      case "^": return finite(a ** b);
    }
  };

  // Flattens arguments into [{ v, direct }] in order; ranges expand row by row.
  const items = (args) => {
    const out = [];
    for (const a of args) {
      if (a.k === "range") for (const addr of rangeAddrs(a)) out.push({ v: lookup(addr), direct: false });
      else out.push({ v: ev(a), direct: true });
    }
    return out;
  };

  const call = (n) => {
    const ar = ARITY[n.name];
    if (!ar) return "#NAME?";
    const args = n.args;
    if (args.length < ar[0] || args.length > ar[1]) return "#VALUE!";
    const one = (i) => ev(args[i]);
    switch (n.name) {
      case "IF": {
        const c = one(0);
        if (isErr(c)) return c;
        const b = toBool(c);
        if (isErr(b)) return b;
        return b ? ev(args[1]) : args.length > 2 ? ev(args[2]) : false;
      }
      case "NOT": {
        const c = one(0);
        if (isErr(c)) return c;
        const b = toBool(c);
        return isErr(b) ? b : !b;
      }
      case "AND": case "OR": {
        const isAnd = n.name === "AND";
        let res = isAnd;
        for (const { v, direct } of items(args)) {
          if (isErr(v) && (direct || true)) return v;
          let b;
          if (direct) { b = toBool(v); if (isErr(b)) return b; }
          else if (typeof v === "number" || typeof v === "boolean") b = toBool(v);
          else continue;
          res = isAnd ? res && b : res || b;
        }
        return res;
      }
      case "ROUND": {
        const x = one(0);
        if (isErr(x)) return x;
        const d = one(1);
        if (isErr(d)) return d;
        const a = toNum(x);
        if (isErr(a)) return a;
        const b = toNum(d);
        if (isErr(b)) return b;
        return finite(round(a, b));
      }
      case "ABS": {
        const x = one(0);
        if (isErr(x)) return x;
        const a = toNum(x);
        return isErr(a) ? a : Math.abs(a);
      }
      case "LEN": case "UPPER": case "LOWER": {
        const x = one(0);
        if (isErr(x)) return x;
        const t = toText(x);
        return n.name === "LEN" ? t.length : n.name === "UPPER" ? t.toUpperCase() : t.toLowerCase();
      }
      case "CONCAT": {
        let s = "";
        for (const { v } of items(args)) {
          if (isErr(v)) return v;
          s += toText(v);
        }
        return s;
      }
      case "COUNT": {
        let c = 0;
        for (const { v } of items(args)) if (typeof v === "number") c++;
        return c;
      }
      default: {
        const nums = [];
        for (const { v, direct } of items(args)) {
          if (isErr(v)) return v;
          if (direct) {
            const x = toNum(v);
            if (isErr(x)) return x;
            nums.push(x);
          } else if (typeof v === "number") nums.push(v);
        }
        switch (n.name) {
          case "SUM": return finite(nums.reduce((a, b) => a + b, 0));
          case "AVERAGE": return nums.length ? finite(nums.reduce((a, b) => a + b, 0) / nums.length) : "#DIV/0!";
          case "MIN": return nums.length ? Math.min(...nums) : 0;
          case "MAX": return nums.length ? Math.max(...nums) : 0;
        }
      }
    }
  };

  return ev(ast);
}
