import { test } from "node:test";
import assert from "node:assert/strict";
import { parseFormula, refsOf, evaluate } from "../src/formula.mjs";

const cells = { A1: 1, A2: 2, B1: "x", B2: null, C1: "#REF!" };
const run = (t) => evaluate(parseFormula(t), (a) => cells[a] ?? null);

test("operators and values", () => {
  assert.equal(run("-2^2"), 4);
  assert.equal(run("2^3^2"), 64);
  assert.equal(run('"a""b"&1+2'), 'a"b3');
  assert.equal(run("1/0"), "#DIV/0!");
  assert.equal(run('"abc"<TRUE'), true);
  assert.equal(run("A1:A2"), "#VALUE!");
  assert.equal(run("$a$1 + b2"), 1);
  assert.throws(() => parseFormula("1+"), SyntaxError);
});

test("functions", () => {
  assert.equal(run("sum(A1:B2, 3)"), 6);
  assert.equal(run("COUNT(A1:B2, \"x\")"), 2);
  assert.equal(run("SUM(A1:C1)"), "#REF!");
  assert.equal(run("ROUND(-2.5,0)"), -3);
  assert.equal(run("IF(FALSE,1/0)"), false);
  assert.equal(run("FOO(1)"), "#NAME?");
  assert.equal(run("NOT()"), "#VALUE!");
});

test("refsOf", () => {
  assert.deepEqual(refsOf(parseFormula("B2:A1+$A$1+c3")), ["A1", "B1", "A2", "B2", "C3"]);
});
