// Recalculation: cell values from raw text, with cycle detection and dependency ordering.
import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, toAddr, compareAddr } from "./addr.mjs";
import { cellAddrs } from "./sheet.mjs";

export function valueOf(raw) {
  if (raw === "") return null;
  const t = raw.trim();
  if (t !== "") {
    const n = Number(t);
    if (Number.isFinite(n)) return n;
  }
  const u = raw.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw[0] === "'") return raw.slice(1);
  return raw;
}

const norm = (addr) => { const a = parseAddr(addr); return toAddr(a.col, a.row); };

// Parses every formula cell: Map addr -> { ast, deps } (ast null if it does not parse).
function parseFormulas(sheet) {
  const out = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (raw[0] !== "=") continue;
    try {
      const ast = parseFormula(raw.slice(1));
      out.set(addr, { ast, deps: refsOf(ast).filter((d) => sheet.cells.get(d)?.[0] === "=") });
    } catch {
      out.set(addr, { ast: null, deps: [] });
    }
  }
  return out;
}

// Iterative Tarjan. Calls onScc(members, cyclic) with dependencies' components first.
function components(formulas, onScc) {
  const index = new Map(), low = new Map(), onStack = new Set(), stack = [];
  let next = 0;
  for (const root of formulas.keys()) {
    if (index.has(root)) continue;
    const work = [[root, 0]];
    index.set(root, next); low.set(root, next++); stack.push(root); onStack.add(root);
    while (work.length) {
      const frame = work[work.length - 1];
      const [v, i] = frame;
      const deps = formulas.get(v).deps;
      if (i < deps.length) {
        frame[1]++;
        const w = deps[i];
        if (!index.has(w)) {
          index.set(w, next); low.set(w, next++); stack.push(w); onStack.add(w);
          work.push([w, 0]);
        } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) { const p = work[work.length - 1][0]; low.set(p, Math.min(low.get(p), low.get(v))); }
        if (low.get(v) === index.get(v)) {
          const members = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); members.push(w); } while (w !== v);
          onScc(members, members.length > 1 || deps.includes(v));
        }
      }
    }
  }
}

export function computeAll(sheet) {
  const values = new Map();
  const formulas = parseFormulas(sheet);
  for (const [addr, raw] of sheet.cells) if (!formulas.has(addr)) values.set(addr, valueOf(raw));
  const lookup = (a) => values.get(norm(a)) ?? null;
  components(formulas, (members, cyclic) => {
    for (const addr of members) {
      const { ast } = formulas.get(addr);
      values.set(addr, cyclic ? "#CYCLE!" : ast ? evaluate(ast, lookup) : "#ERROR!");
    }
  });
  return new Map(cellAddrs(sheet).map((a) => [a, values.get(a)]));
}

export function dependents(sheet, addr) {
  const start = norm(addr);
  const formulas = parseFormulas(sheet);
  const cyclic = new Set();
  components(formulas, (members, c) => { if (c) for (const m of members) cyclic.add(m); });
  const readers = new Map();
  for (const [a, { deps }] of formulas) for (const d of deps) (readers.get(d) ?? readers.set(d, []).get(d)).push(a);
  // Direct readers of start (which may be an empty or non-formula cell).
  const direct = [];
  for (const [a, { ast }] of formulas) if (ast && refsOf(ast).includes(start)) direct.push(a);
  const reach = new Set();
  const todo = [...direct];
  while (todo.length) {
    const a = todo.pop();
    if (reach.has(a)) continue;
    reach.add(a);
    for (const r of readers.get(a) ?? []) todo.push(r);
  }
  const list = [...reach].filter((a) => a !== start && !cyclic.has(a));
  const inList = new Set(list);
  const pending = new Map();
  for (const a of list) pending.set(a, formulas.get(a).deps.filter((d) => inList.has(d) && d !== a).length);
  const ready = list.filter((a) => pending.get(a) === 0).sort(compareAddr);
  const heap = [];
  const push = (a) => {
    heap.push(a);
    for (let i = heap.length - 1; i > 0;) {
      const p = (i - 1) >> 1;
      if (compareAddr(heap[i], heap[p]) >= 0) break;
      [heap[i], heap[p]] = [heap[p], heap[i]]; i = p;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      for (let i = 0; ;) {
        let m = i;
        for (const c of [2 * i + 1, 2 * i + 2]) if (c < heap.length && compareAddr(heap[c], heap[m]) < 0) m = c;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]]; i = m;
      }
    }
    return top;
  };
  ready.forEach(push);
  const out = [];
  while (heap.length) {
    const a = pop();
    out.push(a);
    for (const r of new Set(readers.get(a) ?? [])) {
      if (!inList.has(r) || r === a) continue;
      const n = formulas.get(r).deps.filter((d) => d === a).length;
      pending.set(r, pending.get(r) - n);
      if (pending.get(r) === 0) push(r);
    }
  }
  return out;
}
