// Range operations: sorting rows and pivot tables.
import { parseAddr, toAddr, colIndex } from "./addr.mjs";
import { getCell, setCell } from "./sheet.mjs";
import { valueOf } from "./recalc.mjs";

function parseRange(range) {
  const [a, b] = range.split(":").map(parseAddr);
  return { c1: Math.min(a.col, b.col), c2: Math.max(a.col, b.col), r1: Math.min(a.row, b.row), r2: Math.max(a.row, b.row) };
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

// Compares two non-empty values: numbers, then strings (case-insensitive), then booleans.
function compareValues(x, y) {
  const rx = rank(x), ry = rank(y);
  if (rx !== ry) return rx - ry;
  if (rx === 1) { x = x.toLowerCase(); y = y.toLowerCase(); }
  return x < y ? -1 : x > y ? 1 : 0;
}

export function sortRange(sheet, range, keys, options = {}) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const start = options.header ? r1 + 1 : r1;
  const rows = [];
  for (let r = start; r <= r2; r++) {
    const raws = [];
    for (let c = c1; c <= c2; c++) raws.push(getCell(sheet, toAddr(c, r)));
    rows.push({ raws, vals: raws.map(valueOf) });
  }
  const cols = keys.map((k) => ({ i: colIndex(k.col) - c1, desc: !!k.desc }));
  rows.sort((a, b) => {
    for (const { i, desc } of cols) {
      const x = a.vals[i], y = b.vals[i];
      if (x === null || y === null) {
        if (x === y) continue;
        return x === null ? 1 : -1;
      }
      const d = compareValues(x, y);
      if (d) return desc ? -d : d;
    }
    return 0;
  });
  rows.forEach(({ raws }, k) => raws.forEach((raw, j) => setCell(sheet, toAddr(c1 + j, start + k), raw)));
}

export function pivot(values, range, { rows, value, agg }) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const names = new Map();
  for (let c = c1; c <= c2; c++) {
    const n = values.get(toAddr(c, r1));
    if (n != null && !names.has(String(n))) names.set(String(n), c);
  }
  for (const name of [rows, value]) if (!names.has(name)) throw new Error(`no such column: ${name}`);
  const kc = names.get(rows), vc = names.get(value);
  const groups = new Map();
  let blank = null;
  for (let r = r1 + 1; r <= r2; r++) {
    const key = values.get(toAddr(kc, r)) ?? null;
    const v = values.get(toAddr(vc, r)) ?? null;
    let g;
    if (key === null) g = blank ??= { key: "(blank)", vs: [] };
    else g = groups.get(key) ?? groups.set(key, { key, vs: [] }).get(key);
    g.vs.push(v);
  }
  const aggregate = (vs) => {
    if (agg === "count") return vs.filter((v) => v !== null).length;
    const n = vs.filter((v) => typeof v === "number");
    if (agg === "sum") return n.reduce((s, v) => s + v, 0);
    if (!n.length) return null;
    if (agg === "avg") return n.reduce((s, v) => s + v, 0) / n.length;
    if (agg === "min") return Math.min(...n);
    if (agg === "max") return Math.max(...n);
    throw new Error(`unknown aggregate: ${agg}`);
  };
  const out = [...groups.values()].sort((a, b) => compareValues(a.key, b.key));
  if (blank) out.push(blank);
  return out.map((g) => ({ key: g.key, value: aggregate(g.vs) }));
