// Subset of spreadsheet number formats.

function splitSections(pattern) {
  const out = [""];
  let quoted = false;
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    if (c === "\\" && !quoted) {
      out[out.length - 1] += c + (pattern[++i] ?? "");
      continue;
    }
    if (c === '"') quoted = !quoted;
    if (c === ";" && !quoted) out.push("");
    else out[out.length - 1] += c;
  }
  return out;
}

function tokenize(section) {
  const toks = [];
  let inExp = false;
  for (let i = 0; i < section.length; i++) {
    const c = section[i];
    if (c === '"') {
      const end = section.indexOf('"', i + 1);
      const stop = end < 0 ? section.length : end;
      toks.push({ t: "lit", s: section.slice(i + 1, stop) });
      i = stop;
    } else if (c === "\\") {
      toks.push({ t: "lit", s: section[++i] ?? "" });
    } else if ((c === "E" || c === "e") && (section[i + 1] === "+" || section[i + 1] === "-")) {
      toks.push({ t: "exp", plus: section[i + 1] === "+", s: c });
      i++;
      inExp = true;
    } else if (c === "0" || c === "#") {
      toks.push({ t: inExp ? "expd" : "dig", c });
    } else if (c === "." && !inExp) toks.push({ t: "dot" });
    else if (c === "," && !inExp) toks.push({ t: "comma" });
    else if (c === "%") toks.push({ t: "pct" });
    else toks.push({ t: "lit", s: c });
  }
  return toks;
}

// Decimal digits of a non-negative finite number: { digits, point } with value = 0.digits * 10^point
function decompose(x, shift) {
  let [m, e] = x.toString().toLowerCase().split("e");
  let [i, f = ""] = m.split(".");
  let point = i.length + Number(e ?? 0) + shift;
  let digits = i + f;
  const lead = digits.match(/^0*/)[0].length;
  digits = digits.slice(lead);
  point -= lead;
  if (!digits) return { digits: "", point: 0 };
  return { digits, point };
}

// Round digit string to n digits (half up on digits); may carry into a new leading digit.
function roundDigits(digits, n) {
  if (n < 0) return { digits: "", carry: false };
  if (digits.length <= n) return { digits: digits.padEnd(n, "0"), carry: false };
  const up = digits[n] >= "5";
  let kept = digits.slice(0, n).split("").map(Number);
  if (up) {
    let k = n - 1;
    while (k >= 0 && kept[k] === 9) kept[k--] = 0;
    if (k < 0) return { digits: "1" + kept.join(""), carry: true };
    kept[k]++;
  }
  return { digits: kept.join(""), carry: false };
}

function group(s) {
  return s.replace(/\B(?=(\d{3})+$)/g, ",");
}

function render(abs, toks) {
  const pct = toks.some((t) => t.t === "pct");
  const shift = pct ? 2 : 0;
  const sci = toks.some((t) => t.t === "exp");
  const dotIdx = toks.findIndex((t) => t.t === "dot");
  const isFrac = (t, k) => dotIdx >= 0 && k > dotIdx && t.t === "dig";
  const fracToks = toks.filter(isFrac);
  const intToks = toks.filter((t, k) => t.t === "dig" && !isFrac(t, k));
  const minInt = intToks.filter((t) => t.c === "0").length;
  const decimals = fracToks.length;
  const { digits, point } = decompose(abs, shift);

  let intStr, fracStr, expStr = "", zeroResult;
  if (sci) {
    let exp = digits ? point - 1 : 0;
    let r = roundDigits(digits || "0", decimals + 1);
    if (r.carry) exp++;
    const d = r.digits.slice(0, decimals + 1);
    intStr = d[0];
    fracStr = d.slice(1);
    zeroResult = !/[1-9]/.test(d);
    const et = toks.find((t) => t.t === "exp");
    const minExp = toks.filter((t) => t.t === "expd" && t.c === "0").length;
    expStr = et.s + (exp < 0 ? "-" : et.plus ? "+" : "") + String(Math.abs(exp)).padStart(minExp, "0");
  } else {
    const intLen = Math.max(point, 0);
    const all = digits.padStart(digits.length + Math.max(-point, 0), "0");
    const full = (point > 0 ? digits.padEnd(point, "0") : all);
    const ip = point > 0 ? full.slice(0, point) : "";
    const fp = point > 0 ? full.slice(point) : all;
    const r = roundDigits(fp, decimals);
    let fr = r.digits;
    let ipart = ip;
    if (r.carry) {
      fr = fr.slice(1);
      const s = roundDigits("0" + ip, ip.length + 1); // ip + 1
      ipart = String(BigInt(ip || "0") + 1n);
      void s; void intLen;
    }
    intStr = ipart.replace(/^0+/, "");
    fracStr = fr;
    zeroResult = !/[1-9]/.test(intStr + fracStr);
  }
  // drop trailing zeros in '#' places
  let f = fracStr.split("");
  for (let k = fracToks.length - 1; k >= 0 && f[k] === "0" && fracToks[k].c === "#"; k--) f.pop();
  fracStr = f.join("");
  intStr = intStr.padStart(minInt, "0");
  const grouping = toks.some((t, k) => t.t === "comma" && toks.slice(0, k).some((x) => x.t === "dig") && toks.slice(k).some((x) => x.t === "dig"));
  if (grouping) intStr = group(intStr);

  let out = "", intDone = false;
  for (let k = 0; k < toks.length; k++) {
    const t = toks[k];
    if (t.t === "lit") out += t.s;
    else if (t.t === "pct") out += "%";
    else if (t.t === "dig" && !isFrac(t, k)) {
      if (!intDone) { out += intStr; intDone = true; }
    } else if (t.t === "dot") {
      if (!intDone && !intToks.length) intDone = true;
      out += "." + fracStr;
    } else if (t.t === "exp") out += expStr;
  }
  return { text: out, zeroResult };
}

export function formatNumber(value, pattern) {
  if (value === null || value === undefined) return "";
  if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
  if (typeof value !== "number") return String(value);
  if (pattern === "General" || !Number.isFinite(value)) return String(value);

  const sections = splitSections(pattern);
  const neg = value < 0;
  let idx = 0, own = false;
  if (sections.length >= 2 && neg) { idx = 1; own = true; }
  else if (sections.length >= 3 && value === 0) idx = 2;
  const { text, zeroResult } = render(Math.abs(value), tokenize(sections[idx]));
  return neg && !own && !zeroResult ? "-" + text : text;
}
