import { createSheet, setCell, cellAddrs } from "./sheet.mjs";
import { parseAddr, toAddr } from "./addr.mjs";

const text = (v) => (v == null ? "" : v === true ? "TRUE" : v === false ? "FALSE" : String(v));
const quote = (s) => (/[,"\n\r]/.test(s) || s.startsWith(" ") || s.endsWith(" ") ? `"${s.replaceAll('"', '""')}"` : s);

export function toCSV(sheet, values = null) {
  const addrs = cellAddrs(sheet);
  if (!addrs.length) return "";
  let rows = 0, cols = 0;
  for (const a of addrs) {
    const p = parseAddr(a);
    rows = Math.max(rows, p.row + 1);
    cols = Math.max(cols, p.col + 1);
  }
  let out = "";
  for (let r = 0; r < rows; r++) {
    const fields = [];
    for (let c = 0; c < cols; c++) {
      const a = toAddr(c, r);
      fields.push(quote(values ? text(values.get(a)) : sheet.cells.get(a) ?? ""));
    }
    out += fields.join(",") + "\n";
  }
  return out;
}

function detectDelimiter(src) {
  const count = { ",": 0, ";": 0, "\t": 0 };
  let inQ = false;
  for (const ch of src) {
    if (ch === '"') inQ = !inQ;
    else if (!inQ && (ch === "\n" || ch === "\r")) break;
    else if (!inQ && ch in count) count[ch]++;
  }
  let best = ",";
  for (const d of [";", "\t"]) if (count[d] > count[best]) best = d;
  return best;
}

export function fromCSV(src, options = {}) {
  const delim = options.delimiter ?? detectDelimiter(src);
  const sheet = createSheet();
  const rows = [];
  let row = [], field = "", i = 0, line = 1, pending = false;
  const n = src.length;
  while (i < n) {
    pending = true;
    if (src[i] === '"' && field === "") {
      const startLine = line;
      i++;
      for (;;) {
        if (i >= n) throw new Error(`unclosed quote at line ${startLine}`);
        const ch = src[i];
        if (ch === '"') {
          if (src[i + 1] === '"') { field += '"'; i += 2; continue; }
          i++;
          break;
        }
        if (ch === "\n") line++;
        field += ch;
        i++;
      }
      // text after the closing quote up to the delimiter is kept literally
      continue;
    }
    const ch = src[i];
    if (ch === delim) { row.push(field); field = ""; i++; }
    else if (ch === "\n" || (ch === "\r" && src[i + 1] === "\n")) {
      row.push(field); rows.push(row); row = []; field = ""; pending = false;
      i += ch === "\r" ? 2 : 1;
      line++;
    } else { field += ch; i++; }
  }
  if (pending) { row.push(field); rows.push(row); }
  rows.forEach((r, ri) => r.forEach((f, ci) => {
    if (f === "") return;
    setCell(sheet, toAddr(ci, ri), f.startsWith("=") && !options.formulas ? "'" + f : f);
  }));
  return sheet;
}
