import { parseAddr, toAddr, colIndex } from "./addr.mjs";
import { colName } from "./addr.mjs";

const REF = /(\$?[A-Za-z]+\$?\d+)(?::(\$?[A-Za-z]+\$?\d+))?/y;
const isWord = (ch) => ch !== undefined && /[A-Za-z0-9_.]/.test(ch);

const parse = (t) => { try { return parseAddr(t); } catch { return null; } };
const fmt = (p) => `${p.colAbs ? "$" : ""}${colName(p.col)}${p.rowAbs ? "$" : ""}${p.row + 1}`;

// Maps index i for a single cell; null if deleted.
function mapPoint(i, a, count, del) {
  if (i < a) return i;
  if (!del) return i + count;
  return i < a + count ? null : i - count;
}

function mapRange(s, e, a, count, del) {
  if (!del) return [s >= a ? s + count : s, e >= a ? e + count : e];
  const ns = s < a ? s : s < a + count ? a : s - count;
  const ne = e < a ? e : e < a + count ? a - 1 : e - count;
  return ns > ne ? null : [ns, ne];
}

function rewrite(formula, axis, a, count, del) {
  let out = "";
  let i = 0;
  while (i < formula.length) {
    const ch = formula[i];
    if (ch === '"') {
      let j = i + 1;
      while (j < formula.length) {
        if (formula[j] === '"') { if (formula[j + 1] === '"') j += 2; else break; }
        else j++;
      }
      out += formula.slice(i, j + 1);
      i = j + 1;
      continue;
    }
    if (!isWord(formula[i - 1]) && /[$A-Za-z]/.test(ch)) {
      REF.lastIndex = i;
      const m = REF.exec(formula);
      if (m) {
        const p1 = parse(m[1]), p2 = m[2] ? parse(m[2]) : null;
        const tryEnd = (end) => !isWord(formula[end]) && formula[end] !== "(";
        let use = null;
        if (p1 && p2 && tryEnd(i + m[0].length)) use = [p1, p2, m[0]];
        else if (p1 && tryEnd(i + m[1].length)) use = [p1, null, m[1]];
        if (use) {
          const [q1, q2, txt] = use;
          if (!q2) {
            const v = mapPoint(q1[axis], a, count, del);
            if (v === null) out += "#REF!";
            else out += fmt({ ...q1, [axis]: v });
          } else {
            const lo = Math.min(q1[axis], q2[axis]), hi = Math.max(q1[axis], q2[axis]);
            const r = mapRange(lo, hi, a, count, del);
            if (!r) out += "#REF!";
            else {
              const flip = q1[axis] > q2[axis];
              out += fmt({ ...q1, [axis]: flip ? r[1] : r[0] }) + ":" + fmt({ ...q2, [axis]: flip ? r[0] : r[1] });
            }
          }
          i += txt.length;
          continue;
        }
      }
    }
    out += ch;
    i++;
  }
  return out;
}

function apply(sheet, axis, a, count, del) {
  const next = new Map();
  for (const [addr, raw] of sheet.cells) {
    const p = parseAddr(addr);
    const v = mapPoint(p[axis], a, count, del);
    if (v === null) continue;
    next.set(toAddr(axis === "col" ? v : p.col, axis === "row" ? v : p.row),
      raw.startsWith("=") ? rewrite(raw, axis, a, count, del) : raw);
  }
  sheet.cells.clear();
  for (const [k, v] of next) sheet.cells.set(k, v);
}

export const insertRows = (sheet, at, count = 1) => apply(sheet, "row", at - 1, count, false);
export const deleteRows = (sheet, at, count = 1) => apply(sheet, "row", at - 1, count, true);
export const insertCols = (sheet, at, count = 1) => apply(sheet, "col", colIndex(at), count, false);
export const deleteCols = (sheet, at, count = 1) => apply(sheet, "col", colIndex(at), count, true);
